window.getLanguage = function() {
    const stored = localStorage.getItem('preferred_language');
    if (stored && ['ru', 'en', 'de', 'es', 'fr'].includes(stored)) {
        return stored;
    }

    const browser = navigator.language.substring(0, 2).toLowerCase();
    if (['ru', 'en', 'de', 'es', 'fr'].includes(browser)) {
        return browser;
    }

    return 'ru';
};

window.setLanguage = function(lang) {
    if (!['ru', 'en', 'de', 'es', 'fr'].includes(lang)) {
        console.error('Unsupported language:', lang);
        return;
    }
    localStorage.setItem('preferred_language', lang);
    document.documentElement.lang = lang;
};

window.t = function(key, replacements = {}) {
    const lang = window.getLanguage();
    let text = window.translations[lang][key] || key;

    Object.keys(replacements).forEach(placeholder => {
        text = text.replace(new RegExp(`{{${placeholder}}}`, 'g'), replacements[placeholder]);
    });

    return text;
};

window.formatAccountAge = function(dateInput) {
    if (!dateInput) return '';
    const from = (dateInput instanceof Date) ? new Date(dateInput.getTime()) : new Date(dateInput);
    if (isNaN(from.getTime())) return '';
    const lang = window.getLanguage();
    const U = {
        ru: { year: ['год', 'года', 'лет'], month: ['месяц', 'месяца', 'месяцев'], day: ['день', 'дня', 'дней'], newreg: 'Новорег' },
        en: { year: ['year', 'years'], month: ['month', 'months'], day: ['day', 'days'], newreg: 'Brand new' },
        de: { year: ['Jahr', 'Jahre'], month: ['Monat', 'Monate'], day: ['Tag', 'Tage'], newreg: 'Brandneu' },
        es: { year: ['año', 'años'], month: ['mes', 'meses'], day: ['día', 'días'], newreg: 'Nueva' },
        fr: { year: ['an', 'ans'], month: ['mois', 'mois'], day: ['jour', 'jours'], newreg: 'Tout neuf' }
    };
    const data = U[lang] || U.en;
    const to = new Date();
    if (from >= to) return data.newreg;
    let years = to.getFullYear() - from.getFullYear();
    let months = to.getMonth() - from.getMonth();
    let days = to.getDate() - from.getDate();
    if (days < 0) {
        months -= 1;
        days += new Date(to.getFullYear(), to.getMonth(), 0).getDate();
    }
    if (months < 0) {
        years -= 1;
        months += 12;
    }
    if (years === 0 && months === 0 && days === 0) return data.newreg;
    const word = (n, unit) => {
        const f = data[unit];
        if (lang === 'ru') {
            const a = n % 10, b = n % 100;
            if (a === 1 && b !== 11) return f[0];
            if (a >= 2 && a <= 4 && (b < 10 || b >= 20)) return f[1];
            return f[2];
        }
        return n === 1 ? f[0] : f[1];
    };
    const part = (n, unit) => n + ' ' + word(n, unit);
    const out = [];
    if (years > 0) {
        out.push(part(years, 'year'));
        if (months > 0) out.push(part(months, 'month'));
    } else if (months > 0) {
        out.push(part(months, 'month'));
        if (days > 0) out.push(part(days, 'day'));
    } else {
        out.push(part(days, 'day'));
    }
    return out.join(' ');
};

window.formatDate = function(dateInput) {
    if (!dateInput) return '';
    const d = (dateInput instanceof Date) ? dateInput : new Date(dateInput);
    if (isNaN(d.getTime())) return '';
    const locales = { ru: 'ru-RU', en: 'en-US', de: 'de-DE', es: 'es-ES', fr: 'fr-FR' };
    return d.toLocaleDateString(locales[window.getLanguage()] || 'en-US');
};

