window.tServer = function(msg) {
    if (msg == null) return msg;
    const lang = window.getLanguage();
    const text = String(msg);

    if (lang === 'ru') {
        const statRu = window.SERVER_STATIC_MESSAGES[text];
        return (statRu && statRu.ru) ? statRu.ru : msg;
    }

    const stat = window.SERVER_STATIC_MESSAGES[text];
    if (stat) return stat[lang] || text;

    for (let i = 0; i < window.SERVER_DYNAMIC_MESSAGES.length; i++) {
        const rule = window.SERVER_DYNAMIC_MESSAGES[i];
        const m = text.match(rule[0]);
        if (m) {
            const r = rule[1](m);
            return r[lang] || text;
        }
    }

    return text;
};

// Загрузка серверной настройки spinnerType в localStorage + оповещение страниц.
// Позволяет всем страницам (init из localStorage + слушатель storage) реагировать на настройку.
window.applySpinnerType = function(value) {
    if (value !== 'dots' && value !== 'blocks') return;
    if (localStorage.getItem('spinnerType') === value) return;
    localStorage.setItem('spinnerType', value);
    try {
        window.dispatchEvent(new StorageEvent('storage', { key: 'spinnerType', newValue: value }));
    } catch (e) {
        window.dispatchEvent(new Event('spinnerTypeChanged'));
    }
};

(function loadSpinnerSetting() {
    try {
        const token = localStorage.getItem('access_token');
        if (!token) return;
        fetch('/api/v1/users/me/settings', { headers: { 'Authorization': 'Bearer ' + token } })
            .then(function (r) { return r.ok ? r.json() : null; })
            .then(function (settings) {
                if (settings && settings.spinnerType) {
                    window.applySpinnerType(settings.spinnerType);
                }
            })
            .catch(function () {});
    } catch (e) {}
})();
